package de.nsn.neo.data;
import android.content.Context; import android.content.SharedPreferences; import de.nsn.neo.model.SourceId; import de.nsn.neo.model.ContentType; import de.nsn.neo.model.MediaItem; import java.util.*; import org.json.*;
public final class LibraryStore {
 private final SharedPreferences preferences; public LibraryStore(Context c){preferences=c.getApplicationContext().getSharedPreferences("nsn_library_v1",Context.MODE_PRIVATE);}
 public synchronized void savePlayback(PlaybackRecord r){if(r==null||r.positionMs<5000)return;List<PlaybackRecord>x=playback();x.removeIf(v->key(v).equals(key(r)));if(r.durationMs<=0||r.positionMs<r.durationMs-30000)x.add(r);x.sort(Comparator.comparingLong((PlaybackRecord v)->v.updatedAt).reversed());JSONArray a=new JSONArray();for(int i=0;i<Math.min(50,x.size());i++)a.put(json(x.get(i)));preferences.edit().putString("playback",a.toString()).apply();}
 public synchronized List<PlaybackRecord> playback(){List<PlaybackRecord>x=new ArrayList<>();try{JSONArray a=new JSONArray(preferences.getString("playback","[]"));for(int i=0;i<a.length();i++)x.add(record(a.getJSONObject(i)));}catch(Exception e){preferences.edit().remove("playback").apply();}x.sort(Comparator.comparingLong((PlaybackRecord v)->v.updatedAt).reversed());return x;}
 public synchronized void removePlayback(PlaybackRecord record){if(record==null)return;List<PlaybackRecord>x=playback();x.removeIf(v->key(v).equals(key(record)));JSONArray a=new JSONArray();for(PlaybackRecord v:x)a.put(json(v));preferences.edit().putString("playback",a.toString()).apply();}
 public synchronized long resumePosition(SourceId s,String c,String e){for(PlaybackRecord r:playback())if(r.source==s&&same(r.contentId,c)&&same(r.episodeId,e))return r.positionMs;return 0;}
 public synchronized boolean isFavorite(SourceId source,String id){for(MediaItem item:favorites())if(item.source==source&&same(item.id,id))return true;return false;}
 public synchronized boolean toggleFavorite(MediaItem item){List<MediaItem>x=favorites();boolean removed=x.removeIf(v->v.source==item.source&&same(v.id,item.id));if(!removed)x.add(0,item);JSONArray a=new JSONArray();for(MediaItem v:x)a.put(mediaJson(v));preferences.edit().putString("favorites",a.toString()).apply();return !removed;}
 public synchronized List<MediaItem> favorites(){List<MediaItem>x=new ArrayList<>();try{JSONArray a=new JSONArray(preferences.getString("favorites","[]"));for(int i=0;i<a.length();i++)x.add(media(a.getJSONObject(i)));}catch(Exception e){preferences.edit().remove("favorites").apply();}return x;}
 private static boolean same(String a,String b){return a==null?b==null:a.equals(b);} private static String key(PlaybackRecord r){return r.source+"|"+r.contentId+"|"+r.episodeId;}
 private static JSONObject json(PlaybackRecord r){JSONObject j=new JSONObject();try{j.put("source",r.source.name());j.put("content",r.contentId);j.put("episode",r.episodeId);j.put("title",r.title);j.put("subtitle",r.subtitle);j.put("poster",r.posterUrl);j.put("position",r.positionMs);j.put("duration",r.durationMs);j.put("updated",r.updatedAt);}catch(Exception ignored){}return j;}
 private static PlaybackRecord record(JSONObject j){return new PlaybackRecord(SourceId.valueOf(j.optString("source")),j.optString("content"),j.optString("episode"),j.optString("title"),j.optString("subtitle"),j.optString("poster",null),j.optLong("position"),j.optLong("duration"),j.optLong("updated"));}
 private static JSONObject mediaJson(MediaItem v){JSONObject j=new JSONObject();try{j.put("id",v.id);j.put("source",v.source.name());j.put("type",v.type.name());j.put("title",v.title);j.put("description",v.description);j.put("poster",v.posterUrl);j.put("backdrop",v.backdropUrl);j.put("detail",v.detailUrl);j.put("year",v.year);j.put("rating",v.rating);j.put("genres",new JSONArray(v.genres));}catch(Exception ignored){}return j;}
 private static MediaItem media(JSONObject j){List<String>g=new ArrayList<>();JSONArray a=j.optJSONArray("genres");if(a!=null)for(int i=0;i<a.length();i++)g.add(a.optString(i));return new MediaItem(j.optString("id"),SourceId.valueOf(j.optString("source")),ContentType.valueOf(j.optString("type")),j.optString("title"),j.optString("description"),j.optString("poster",null),j.optString("backdrop",null),j.optString("detail",null),g,j.optString("year",null),j.optString("rating",null));}
}
